// The member register (P1.2): exports of the register as CSV files in object
// storage, generated by the worker and deleted after 24 hours.

import {
  MEMBER_EXPORT_COLUMNS,
  MEMBER_EXPORT_STATUSES,
  type MemberExportColumn,
  type MemberExportStatus,
  type RegisterFilter,
} from "@clubadmin/shared";
import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

import { clubRef, personRef } from "./clubs.ts";
import { id, oneOf, subsetOf, timestamps, tz } from "./columns.ts";

export const memberExports = pgTable(
  "member_exports",
  {
    id: id(),
    clubId: clubRef(),
    requestedByPersonId: personRef(),
    status: text().$type<MemberExportStatus>().notNull().default("queued"),
    /** The register filter (IDs and enum values only). */
    filter: jsonb().$type<RegisterFilter>().notNull().default({}),
    columns: text().array().$type<MemberExportColumn[]>().notNull(),
    includeProtected: boolean().notNull().default(false),
    rowCount: integer(),
    /** exports/<club_id>/<id>.csv in the files bucket, once ready. */
    objectKey: text(),
    expiresAt: timestamp(tz),
    errorCode: text(),
    ...timestamps,
  },
  (t) => [
    check("member_exports_status", oneOf(t.status, MEMBER_EXPORT_STATUSES)),
    check("member_exports_columns", subsetOf(t.columns, MEMBER_EXPORT_COLUMNS)),
    check(
      "member_exports_ready",
      sql`${t.status} <> 'ready' OR (${t.objectKey} IS NOT NULL AND ${t.expiresAt} IS NOT NULL)`,
    ),
    index("member_exports_club_idx").on(t.clubId, t.createdAt),
    index("member_exports_requester_idx").on(t.requestedByPersonId, t.createdAt),
    index("member_exports_open_idx")
      .on(t.expiresAt)
      .where(sql`${t.status} IN ('queued', 'ready')`),
  ],
);
